"""`hooks service install|uninstall|status|logs`: run hooks in the
background as the current user. Uses a systemd user unit on Linux and a
launchd agent on macOS. Neither needs root."""
from __future__ import annotations

import getpass
import os
import platform
import subprocess
import sys
from pathlib import Path

from hooks import paths

NAME = "hooks"
LABEL = "local.hooks"

SYSTEMD_UNIT = """\
# Generated by `hooks service install`; re-run it after moving the project.
[Unit]
Description=hooks: personal notification hooks
After=network-online.target
Wants=network-online.target

[Service]
WorkingDirectory={root}
Environment=HOOKS_HOME={home}
Environment=PYTHONUNBUFFERED=1
ExecStart={python} -m hooks run
Restart=always
RestartSec=30

[Install]
WantedBy=default.target
"""

LAUNCHD_PLIST = """\
<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by `hooks service install`; re-run it after moving the project. -->
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>{label}</string>
  <key>ProgramArguments</key>
  <array><string>{python}</string><string>-m</string><string>hooks</string><string>run</string></array>
  <key>WorkingDirectory</key><string>{root}</string>
  <key>EnvironmentVariables</key>
  <dict>
    <key>HOOKS_HOME</key><string>{home}</string>
    <key>PYTHONUNBUFFERED</key><string>1</string>
  </dict>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>30</integer>
  <key>StandardOutPath</key><string>{log}</string>
  <key>StandardErrorPath</key><string>{log}</string>
</dict>
</plist>
"""


def _sh(*cmd: str, check: bool = True) -> int:
    print("$", " ".join(cmd))
    return subprocess.run(cmd, check=check).returncode


def _ctx() -> dict:
    return {"root": paths.PROJECT_ROOT, "home": paths.home(), "python": sys.executable, "label": LABEL,
            "log": paths.log_dir() / "hooks.log"}


def _systemd_unit_path() -> Path:
    return Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config")) / "systemd/user" / f"{NAME}.service"


def _plist_path() -> Path:
    return Path.home() / "Library/LaunchAgents" / f"{LABEL}.plist"


def _gui() -> str:
    return f"gui/{os.getuid()}"


def install() -> int:
    system = platform.system()
    if system == "Linux":
        unit = _systemd_unit_path()
        unit.parent.mkdir(parents=True, exist_ok=True)
        unit.write_text(SYSTEMD_UNIT.format(**_ctx()))
        print(f"wrote {unit}")
        _sh("systemctl", "--user", "daemon-reload")
        _sh("systemctl", "--user", "enable", "--now", NAME)
        _sh("systemctl", "--user", "restart", NAME)
        linger = subprocess.run(["loginctl", "show-user", getpass.getuser(), "-p", "Linger", "--value"],
                                capture_output=True, text=True).stdout.strip()
        if linger != "yes":
            print("\n!! Linger is off: the service stops when you log out of your last session.\n"
                  f"   Ask an admin to run once:  sudo loginctl enable-linger {getpass.getuser()}")
        print(f"\nlogs:  journalctl --user -u {NAME} -f")
    elif system == "Darwin":
        plist = _plist_path()
        plist.parent.mkdir(parents=True, exist_ok=True)
        paths.log_dir().mkdir(parents=True, exist_ok=True)
        plist.write_text(LAUNCHD_PLIST.format(**_ctx()))
        print(f"wrote {plist}")
        _sh("launchctl", "bootout", f"{_gui()}/{LABEL}", check=False)
        _sh("launchctl", "bootstrap", _gui(), str(plist))
        print(f"\nlogs:  tail -f {_ctx()['log']}")
    else:
        print(f"unsupported platform {system}; run `hooks run` under your own supervisor")
        return 1
    return 0


def uninstall() -> int:
    system = platform.system()
    if system == "Linux":
        _sh("systemctl", "--user", "disable", "--now", NAME, check=False)
        _systemd_unit_path().unlink(missing_ok=True)
        _sh("systemctl", "--user", "daemon-reload")
    elif system == "Darwin":
        _sh("launchctl", "bootout", f"{_gui()}/{LABEL}", check=False)
        _plist_path().unlink(missing_ok=True)
    return 0


def status() -> int:
    if platform.system() == "Linux":
        return _sh("systemctl", "--user", "--no-pager", "status", NAME, check=False)
    if platform.system() == "Darwin":
        return _sh("launchctl", "print", f"{_gui()}/{LABEL}", check=False)
    return 1


def logs() -> int:
    if platform.system() == "Linux":
        return _sh("journalctl", "--user", "-u", NAME, "-f", check=False)
    if platform.system() == "Darwin":
        return _sh("tail", "-n", "100", "-f", str(_ctx()["log"]), check=False)
    return 1


def restart() -> int:
    if platform.system() == "Linux":
        return _sh("systemctl", "--user", "restart", NAME)
    if platform.system() == "Darwin":
        return _sh("launchctl", "kickstart", "-k", f"{_gui()}/{LABEL}")
    return 1


ACTIONS = {"install": install, "uninstall": uninstall, "status": status, "logs": logs, "restart": restart}
